define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_24.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e147552","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_23.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e147656","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_18.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e147760","topics":[]},{"title":"Removing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Removes the rear trim ring from the rear endbell.  The trim ring covers the bolts securing the magnet rear enclosures.<\/p>","href":"t_RemovingTheRearTrimRing_11.html","attributes":{"data-id":"id_2002972"},"menu":{"hasChildren":false},"tocID":"id_2002972-d46e147864","topics":[]},{"title":"Removing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cable cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearCableCover_10.html","attributes":{"data-id":"id_2002978"},"menu":{"hasChildren":false},"tocID":"id_2002978-d46e147968","topics":[]},{"title":"Installing the hoist","shortdesc":"<p class=\"shortdesc\">Install the hoist in order to replace components within the Integrated System Cabinet (ISC) and Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheHoist_4.html","attributes":{"data-id":"id_2003492"},"menu":{"hasChildren":false},"tocID":"id_2003492-d46e148072","topics":[]},{"title":"Removing the Gradient Cooling Unit (GCU)","shortdesc":"<p class=\"shortdesc\">Remove the GCU from the Integrated Cooling Cabinet (ICC).<\/p>","href":"t_RemovingTheGCU.html","attributes":{"data-id":"id_2001865"},"menu":{"hasChildren":false},"tocID":"id_2001865-d46e148176","topics":[]},{"title":"Installing the Gradient Coiling Unit (GCU)","shortdesc":"<p class=\"shortdesc\">Install the GCU in the Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheGCU.html","attributes":{"data-id":"id_2002034"},"menu":{"hasChildren":false},"tocID":"id_2002034-d46e148280","topics":[]},{"title":"Refilling the Integrated Cooling Cabinet (ICC) coolant","shortdesc":"<p class=\"shortdesc\">Fill the Cabinet Cooling Unit (CCU) and Gradient Cooling Unit (GCU) tanks with coolant, as needed.<\/p>","href":"t_RefillingCoolant_4.html","attributes":{"data-id":"id_2002771"},"menu":{"hasChildren":false},"tocID":"id_2002771-d46e148384","topics":[]},{"title":"Removing the hoist","shortdesc":"<p class=\"shortdesc\">Remove the hoist beam and return it to its storage location.<\/p>","href":"t_RemovingTheHoist_4.html","attributes":{"data-id":"id_2003868"},"menu":{"hasChildren":false},"tocID":"id_2003868-d46e148488","topics":[]},{"title":"Installing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Install the rear cable cover onto the magnet enclosure.<\/p>","href":"t_InstallingTheRearCableCover_10.html","attributes":{"data-id":"id_2002979"},"menu":{"hasChildren":false},"tocID":"id_2002979-d46e148593","topics":[]},{"title":"Installing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Installs the rear trim ring onto the rear endbell.<\/p>","href":"t_InstallingTheRearTrimRing_11.html","attributes":{"data-id":"id_2002973"},"menu":{"hasChildren":false},"tocID":"id_2002973-d46e148697","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_20.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e148801","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_23.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e148905","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_41.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e149009","topics":[]}]});